import{_ as a,o as l,c as t,aw as n}from"./chunks/framework.DLufY-ao.js";const o="/workbook/assets/stash-options.Cn1mMYK3.svg",g=JSON.parse('{"title":"git stash","description":"","frontmatter":{},"headers":[],"relativePath":"common/git/command/stash.md","filePath":"wiki/dev-commit/common/git/command/stash.md"}'),e={name:"common/git/command/stash.md"};function i(p,s,c,r,h,d){return l(),t("div",null,[...s[0]||(s[0]=[n(`<h1 id="git-stash" tabindex="-1"><code>git stash</code> <a class="header-anchor" href="#git-stash" aria-label="Permalink to &quot;\`git stash\`&quot;">​</a></h1><h2 id="информация" tabindex="-1">Информация <a class="header-anchor" href="#информация" aria-label="Permalink to &quot;Информация&quot;">​</a></h2><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p><strong><code>git stash</code></strong> - сменить ветку, не теряя текущих незакоммиченных правок</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><ul><li><a href="https://www.atlassian.com/ru/git/tutorials/saving-changes/git-stash" target="_blank" rel="noreferrer">https://www.atlassian.com/ru/git/tutorials/saving-changes/git-stash</a></li></ul></div><h2 id="алгоритм" tabindex="-1">Алгоритм <a class="header-anchor" href="#алгоритм" aria-label="Permalink to &quot;Алгоритм&quot;">​</a></h2><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> add</span><span style="color:#50A14F;"> .</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Сменить ветку</span></span>
<span class="line"><span style="color:#A0A1A7;font-style:italic;"># Вернуться обратно на ветку, где был stash</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#50A14F;"> pop</span></span></code></pre></div><h2 id="категории-фаилов-для-stash" tabindex="-1">Категории файлов для stash <a class="header-anchor" href="#категории-фаилов-для-stash" aria-label="Permalink to &quot;Категории файлов для stash&quot;">​</a></h2><img src="`+o+`" style="width:500px;"><p>По умолчанию команда git stash создает следующие отложенные изменения:</p><ul><li>Изменения, добавленные в раздел проиндексированных файлов (индексированные изменения)</li><li>Изменения в файлах, отслеживаемых Git в настоящее время (неиндексированные изменения)</li></ul><p>При этом следующие файлы отложены не будут:</p><ul><li>Новые файлы в рабочей копии, которые еще не были проиндексированы</li><li>Игнорируемые файлы</li></ul><h2 id="операции" tabindex="-1">Операции <a class="header-anchor" href="#операции" aria-label="Permalink to &quot;Операции&quot;">​</a></h2><h3 id="сохранение-состояния-рабочеи-директории-и-индекса" tabindex="-1">Сохранение состояния рабочей директории и Индекса <a class="header-anchor" href="#сохранение-состояния-рабочеи-директории-и-индекса" aria-label="Permalink to &quot;Сохранение состояния рабочей директории и Индекса&quot;">​</a></h3><ul><li>Команда <em>git stash</em> сохраняет неподтвержденные изменения (индексированные и неиндексированные) в отдельном хранилище, чтобы можно было вернуться к ним позже. Затем происходит откат до исходной рабочей копии</li><li>Отложенные изменения сохраняются в локальном репозитории Git и не передаются на сервер при выполнении команды <em>push</em></li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span></span></code></pre></div><h3 id="применение-отложенных-изменении" tabindex="-1">Применение отложенных изменений <a class="header-anchor" href="#применение-отложенных-изменении" aria-label="Permalink to &quot;Применение отложенных изменений&quot;">​</a></h3><ul><li>При извлечении отложенных изменений они удаляются из набора и применяются к рабочей копии</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#50A14F;"> pop</span></span></code></pre></div><ul><li>Также можно применить изменения к рабочей копии, не удаляя их из набора отложенных изменений</li><li>Это полезно, если нужно применить одни и те же отложенные изменения к нескольким веткам</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#50A14F;"> apply</span></span></code></pre></div><h3 id="откладывание-неотслеживаемых-или-игнорируемых-фаилов" tabindex="-1">Откладывание неотслеживаемых или игнорируемых файлов <a class="header-anchor" href="#откладывание-неотслеживаемых-или-игнорируемых-фаилов" aria-label="Permalink to &quot;Откладывание неотслеживаемых или игнорируемых файлов&quot;">​</a></h3><ul><li>Позволяет отложить неотслеживаемые файлы</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;"># Аналогично</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#986801;"> -u</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#986801;"> --include-untracked</span></span></code></pre></div><ul><li>Позволяет отложить изменения, внесенные в игнорируемые файлы</li></ul><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#A0A1A7;font-style:italic;"># Аналогично</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#986801;"> -a</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#986801;"> --all</span></span></code></pre></div><h3 id="удаление-отложенных-изменении" tabindex="-1">Удаление отложенных изменений <a class="header-anchor" href="#удаление-отложенных-изменении" aria-label="Permalink to &quot;Удаление отложенных изменений&quot;">​</a></h3><div class="language-bash"><button title="Скопировать код" class="copy"></button><span class="lang">bash</span><pre class="shiki one-light vp-code" tabindex="0"><code><span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#50A14F;"> drop</span><span style="color:#50A14F;"> stash@{</span><span style="color:#986801;">1</span><span style="color:#50A14F;">}</span><span style="color:#A0A1A7;font-style:italic;"> # Удалить определенный набор отложенных изменений</span></span>
<span class="line"><span style="color:#4078F2;">git</span><span style="color:#50A14F;"> stash</span><span style="color:#50A14F;"> clear</span><span style="color:#A0A1A7;font-style:italic;">          # Удалить все наборы отложенных изменений</span></span></code></pre></div>`,28)])])}const b=a(e,[["render",i]]);export{g as __pageData,b as default};
